async function prepareLegacyExport(print){
 let html=buildExportHtml(),stamp=d.reportDate||new Date().toISOString().slice(0,10),base="А-Темир_Строй_отчет_"+stamp;
 try{if(window.atemirDesktop){let r=print?await window.atemirDesktop.savePdf({filename:base+".pdf",html}):await window.atemirDesktop.saveHtml({filename:base+".html",html});if(r&&r.ok)alert((print?"PDF":"HTML")+" сохранён:\n"+r.path);return}let blob=new Blob([html],{type:"text/html;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=base+".html";document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},700)}catch(e){alert("Не удалось выгрузить отчёт: "+(e?.message||e))}
}
